object Main {def main(args:Array[String]):Unit={val x=scala.collection.immutable.SortedSet(1,3);val y=scala.collection.immutable.SortedSet(2,3);val u:scala.collection.immutable.SortedSet[Int]=x|y;val i:scala.collection.immutable.SortedSet[Int]=x&y;val f:scala.collection.immutable.SortedSet[Int]=x.flatMap(n=>List(n,n+1));println(u.mkString(","));println(i.mkString(","));println(f.mkString(","))}}
